// Jsoup版 Readability：基于段落密度、链接密度和噪声节点评分，不依赖站点固定 CSS。
var READABILITY_SCORE_ATTR = 'data-legado-readability-score';
var READABILITY_POSITIVE = /article|body|content|entry|hentry|main|page|post|richtext|story|text/i;
var READABILITY_NEGATIVE = /comment|footer|nav|menu|related|sidebar|social|share|promo|subscribe|advert|banner|breadcrumb|cookie|modal|pagination|toolbar/i;

function readabilityClassAndId(el) {
    try {
        return (String(el.className() || '') + ' ' + String(el.id() || '')).toLowerCase();
    } catch (e) {
        return '';
    }
}

function readabilityIsNoise(el) {
    return READABILITY_NEGATIVE.test(readabilityClassAndId(el));
}

function readabilityClassWeight(el) {
    var value = readabilityClassAndId(el);
    var weight = 0;
    if (READABILITY_POSITIVE.test(value)) weight += 25;
    if (READABILITY_NEGATIVE.test(value)) weight -= 40;
    return weight;
}

function readabilityAddScore(el, score) {
    if (el == null || readabilityIsNoise(el)) return;
    var tag = String(el.tagName()).toLowerCase();
    if (tag === 'html' || tag === 'body') return;
    var previous = parseFloat(String(el.attr(READABILITY_SCORE_ATTR) || '0'));
    if (isNaN(previous)) previous = 0;
    el.attr(READABILITY_SCORE_ATTR, String(previous + score));
}

function readabilityNextPayload(inputDoc) {
    var scripts = inputDoc.select('script');
    var payload = '';
    for (var i = 0; i < scripts.size(); i++) {
        var data = '';
        try { data = String(scripts.get(i).data()); } catch (e) { data = String(scripts.get(i).html()); }
        if (data.indexOf('__next_f.push') >= 0) payload += data + '\n';
    }
    return payload;
}

function readabilityNextDocument(payload) {
    if (!payload || String(payload).length < 100) return null;
    var html = String(payload)
        .replace(/\\u003[cC]/g, '<')
        .replace(/\\u003[eE]/g, '>')
        .replace(/\\u0026/g, '&')
        .replace(/\\u0022/g, '"')
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n');
    var nextDoc = org.jsoup.Jsoup.parse('<article class="legado-next-payload">' + html + '</article>');
    var article = nextDoc.select('article.legado-next-payload').first();
    return article != null && String(article.text()).trim().length >= 200 ? nextDoc : null;
}

function extractReadableContent(inputDoc) {
    var paragraphs = inputDoc.select('p, pre, blockquote, td');
    for (var i = 0; i < paragraphs.size(); i++) {
        var paragraph = paragraphs.get(i);
        if (readabilityIsNoise(paragraph)) continue;
        var text = String(paragraph.text()).trim();
        if (text.length < 40) continue;
        var punctuation = (text.match(/[,，;；:：]/g) || []).length;
        var score = 1 + Math.min(3, Math.floor(text.length / 100)) + Math.min(3, punctuation);
        readabilityAddScore(paragraph.parent(), score);
        readabilityAddScore(paragraph.parent() == null ? null : paragraph.parent().parent(), score / 2);
    }

    var candidates = inputDoc.select('[' + READABILITY_SCORE_ATTR + ']');
    var best = null;
    var bestScore = 0;
    for (var j = 0; j < candidates.size(); j++) {
        var candidate = candidates.get(j);
        var textLength = String(candidate.text()).trim().length;
        if (textLength < 200) continue;
        var linkLength = String(candidate.select('a').text()).trim().length;
        var linkDensity = textLength === 0 ? 1 : linkLength / textLength;
        var score = parseFloat(String(candidate.attr(READABILITY_SCORE_ATTR) || '0'));
        if (isNaN(score)) score = 0;
        score = score * (1 - Math.min(0.9, linkDensity)) + readabilityClassWeight(candidate);
        if (score > bestScore) {
            best = candidate;
            bestScore = score;
        }
    }
    if (best == null) return null;

    var readable = best.clone();
    readable.removeAttr(READABILITY_SCORE_ATTR);
    var scored = readable.select('[' + READABILITY_SCORE_ATTR + ']');
    for (var k = 0; k < scored.size(); k++) scored.get(k).removeAttr(READABILITY_SCORE_ATTR);
    readable.select('script,noscript,style,svg,nav,aside,header,footer,form,button,input,iframe,[hidden],[aria-hidden=true]').remove();
    var descendants = readable.select('*');
    for (var m = descendants.size() - 1; m >= 0; m--) {
        if (readabilityIsNoise(descendants.get(m))) descendants.get(m).remove();
    }
    return String(readable.text()).trim().length >= 200 ? readable : null;
}

var readable = extractReadableContent(doc);
// Next.js 有时仅返回 next-route-announcer 壳；仅在常规正文提取失败时，
// 从随页面返回的 RSC 数据流恢复段落，再复用同一套通用 Readability。
if (readable == null && nextRscPayload.length > 0) {
    var nextDoc = readabilityNextDocument(nextRscPayload);
    if (nextDoc != null) readable = extractReadableContent(nextDoc);
}
if (readable != null) doc = readable;

extract_selector.forEach(function(css) {
    doc.select(css).forEach(function(element) {
        element.replaceWith(element.html());
    });
});

doc.select('a:has(img[loading=lazy])').forEach(function(element) {
    var img = element.select('img').first();
    if (img) {
        var href = element.attr('href');
        if (href) img.attr('src', href);
    }
});

doc.select('img[src]').forEach(function(img) {
    var attributes = img.attributes().iterator();
    while (attributes.hasNext()) {
        var attr = attributes.next();
        if (attr.getKey() !== 'src') attributes.remove();
    }
});

result = TC(doc.html(), java, cache);
result;
